local function makeDraggable(dragArea, moveObject)
    local OtErjp, dragInput, dragStart, startPos
    dragArea.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            OtErjp = true; dragStart = input.Position; startPos = moveObject.Position
            input.Changed:Connect(function() if input.UserInputState == Enum.UserInputState.End then OtErjp = false end end)
        end
    end)
    dragArea.InputChanged:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then dragInput = input end
    end)
    qqiQW.InputChanged:Connect(function(input)
        if input == dragInput and OtErjp then
            local ToRCK = input.Position - dragStart
            moveObject.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + ToRCK.X, startPos.Y.Scale, startPos.Y.Offset + ToRCK.Y)
        end
